import math

def checkSquare(num):
    """
    Determines if num is a perfect square and returns the square root.
    If num is a perfect square, returns (squareRoot, True).
    Otherwise, returns (ceilSquareRoot, False).
    """
    sqrt_num = math.isqrt(num)
    if sqrt_num * sqrt_num == num:
        return (sqrt_num, True)
    else:
        return (sqrt_num + 1, False)

