import re

def is_valid_ip(ip):
    """
    Returns True if the given string is a valid IPv4 address, False otherwise.
    """
    pattern = re.compile(r'^(\d{1,3}\.){3}\d{1,3}$')
    if not pattern.match(ip):
        return False
    parts = ip.split('.')
    for part in parts:
        if not 0 <= int(part) <= 255:
            return False
    return True

