def min_difference(arr):
    """
    Returns the minimum difference between any two elements in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    arr.sort()
    min_diff = float('inf')

    for i in range(1, len(arr)):
        diff = arr[i] - arr[i - 1]
        if diff < min_diff:
            min_diff = diff

    return min_diff

