def count_partitions(n):
    """
    Returns the number of ways to partition the integer n.
    """
    # Create a 2D list to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # base case: there's one way to partition 0, that is using 0
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(n + 1):
            if j >= i:
                dp[i][j] = dp[i - 1][j] + dp[i][j - i]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][n]

