def calculate_grade_distribution(file_path='student_grades.txt'):
    """
    Reads the data from the student_grades.txt file and calculates the number of students 
    falling into each grade category, then prints the results.
    """
    grade_distribution = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}

    with open(file_path, 'r') as file:
        lines = file.readlines()
        for line in lines:
            name, grade = line.strip().split()
            grade = int(grade)
            if 90 <= grade <= 100:
                grade_distribution['A'] += 1
            elif 80 <= grade <= 89:
                grade_distribution['B'] += 1
            elif 70 <= grade <= 79:
                grade_distribution['C'] += 1
            elif 60 <= grade <= 69:
                grade_distribution['D'] += 1
            else:
                grade_distribution['F'] += 1

    print(f"A: {grade_distribution['A']}, B: {grade_distribution['B']}, C: {grade_distribution['C']}, D: {grade_distribution['D']}, F: {grade_distribution['F']}")

# Example usage:
