def count_pairs_with_sum(numbers, target_sum):
    """
    Returns the number of unique pairs of numbers from the list that add up to the target sum.
    """
    seen = set()
    pairs = set()

    for number in numbers:
        complement = target_sum - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return len(pairs)

