import os
import shutil

def organize_files_by_extension(directory_path: str) -> dict:
    try:
        if not os.path.exists(directory_path):
            return {
                "success": False,
                "data": "Directory does not exist."
            }

        files_moved = False
        for item in os.listdir(directory_path):
            item_path = os.path.join(directory_path, item)

            if os.path.isfile(item_path):
                files_moved = True
                _, extension = os.path.splitext(item)
                if extension:
                    extension = extension[1:].lower()
                else:
                    extension = "no_extension"

                target_dir = os.path.join(directory_path, extension)
                if not os.path.exists(target_dir):
                    os.makedirs(target_dir)

                shutil.move(item_path, os.path.join(target_dir, item))

        if files_moved:
            return {
                "success": True,
                "data": "Files organized successfully."
            }
        else:
            return {
                "success": True,
                "data": "No files to organize."
            }

    except PermissionError:
        return {
            "success": False,
            "data": "Permission denied while accessing the directory."
        }
    except Exception as e:
        return {
            "success": False,
            "data": f"An error occurred: {str(e)}"
        }

