def processOperations(operations):
    """
    Processes a sequence of operations on a stack and returns the final state of the stack.

    Parameters:
    operations (list of int): A list of integers representing stack operations.

    Returns:
    list of int: The final state of the stack after all operations or an empty list if an invalid operation was encountered.
    """
    stack = []

    for operation in operations:
        # Positive integer: push onto the stack
        if operation > 0:
            stack.append(operation)
        # Zero: duplicate the top element of the stack
        elif operation == 0:
            if stack:
                stack.append(stack[-1])
            else:
                return []
        # Negative integer: pop the specified number of elements
        else:
            num_to_pop = -operation
            if len(stack) < num_to_pop:
                return []
            stack = stack[:-num_to_pop]

    return stack

def normalize_path(path: str) -> str:
    """
    Normalizes the given file system path to its canonical form.
    """
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "..":
            if stack:
                stack.pop()
        elif part == "." or not part:
            continue
        else:
            stack.append(part)

    return "/" + "/".join(stack)

