from collections import deque

def word_ladder_length(start, end, dictionary):
    """
    Returns the length of the shortest transformation sequence from start to end word, using the given dictionary.
    """
    if end not in dictionary:
        return 0

    dictionary = set(dictionary)
    queue = deque([(start, 1)])

    while queue:
        current_word, length = queue.popleft()

        if current_word == end:
            return length

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word in dictionary:
                    dictionary.remove(next_word)
                    queue.append((next_word, length + 1))

    return 0

