def balance_parentheses(s: str) -> str:
    """
    Takes a string containing only parentheses characters '()'
    and returns a balanced version of the string by removing the
    minimum number of parentheses.
    """
    open_count = 0
    result = []

    # First pass: remove unbalanced closing parentheses
    for char in s:
        if char == '(':
            open_count += 1
            result.append(char)
        elif char == ')':
            if open_count > 0:
                open_count -= 1
                result.append(char)

    open_count = 0
    balanced_result = []

    # Second pass: remove surplus opening parentheses from the result
    for char in reversed(result):
        if char == ')':
            open_count += 1
            balanced_result.append(char)
        elif char == '(':
            if open_count > 0:
                open_count -= 1
                balanced_result.append(char)

    return ''.join(reversed(balanced_result))

