def are_isomorphic(str1: str, str2: str) -> bool:
    """
    Determines if two strings are isomorphic.

    Two strings are isomorphic if there is a one-to-one mapping between every character of str1 
    to every character of str2.

    Parameters:
    - str1 (str): The first input string.
    - str2 (str): The second input string of the same length as str1.

    Returns:
    - bool: True if strings are isomorphic, otherwise False.

    Raises:
    - ValueError: If the input strings are of different lengths.
    """
    if len(str1) != len(str2):
        raise ValueError("Strings are of different lengths, cannot be isomorphic")

    mapping_str1_to_str2 = {}
    mapping_str2_to_str1 = {}

    for char1, char2 in zip(str1, str2):
        if char1 in mapping_str1_to_str2:
            if mapping_str1_to_str2[char1] != char2:
                return False
        else:
            mapping_str1_to_str2[char1] = char2

        if char2 in mapping_str2_to_str1:
            if mapping_str2_to_str1[char2] != char1:
                return False
        else:
            mapping_str2_to_str1[char2] = char1

    return True

