reference_solution:
def count_occurrences(arr):
    count_dict = {}
    if not arr:
        return count_dict

    current_num = arr[0]
    count = 0

    for num in arr:
        if num == current_num:
            count += 1
        else:
            count_dict[current_num] = count
            current_num = num
            count = 1
    count_dict[current_num] = count  # for the last set of numbers

    return count_dict

