def longestSubsequence(numbers):
    """
    Returns the length of the longest subsequence where the difference between the highest
    and lowest number in the subsequence is no greater than 1.
    """
    if not numbers:
        return 0

    num_count = {}
    for num in numbers:
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    max_length = 0
    for num in num_count:
        current_length = num_count.get(num, 0) + num_count.get(num + 1, 0)
        if current_length > max_length:
            max_length = current_length

    return max_length

