def tuples_to_dict(tuples):
    """
    Converts a list of tuples into a dictionary where keys are the first elements of the tuples
    and values are lists of the second elements of the tuples that share the same key.

    :param tuples: List of tuples (key, value)
    :return: Dictionary {key: [values]}
    """
    result = {}
    for k, v in tuples:
        if k not in result:
            result[k] = []
        result[k].append(v)
    return result

