import zlib

def verify_compression_integrity(data: bytes, compression_level: int = -1, checksum_type: str = 'adler32') -> bool:
    if checksum_type not in ['adler32', 'crc32']:
        raise ValueError("Invalid checksum type. Choose either 'adler32' or 'crc32'.")

    # Compute the initial checksum of the original data
    if checksum_type == 'adler32':
        initial_checksum = zlib.adler32(data)
    else:
        initial_checksum = zlib.crc32(data)

    # Compress the data
    compressed_data = zlib.compress(data, level=compression_level)

    # Decompress the data
    decompressed_data = zlib.decompress(compressed_data)

    # Compute the checksum of the decompressed data
    if checksum_type == 'adler32':
        decompressed_checksum = zlib.adler32(decompressed_data)
    else:
        decompressed_checksum = zlib.crc32(decompressed_data)

    # Compare the initial and final checksums to verify data integrity
    return initial_checksum == decompressed_checksum

