def compress_path(path: str) -> str:
    """
    Compress a file path by replacing sequences of identical sub-directory names with the name 
    followed by the number of occurrences.

    :param path: The input file path
    :type path: str
    :return: The compressed file path
    :rtype: str
    """
    if not path:
        return ""

    parts = path.split('/')
    compressed_parts = []

    current = parts[0]
    count = 1

    for part in parts[1:]:
        if part == current:
            count += 1
        else:
            if count > 1:
                compressed_parts.append(f"{current}{count}")
            else:
                compressed_parts.append(current)
            current = part
            count = 1

    if count > 1:
        compressed_parts.append(f"{current}{count}")
    else:
        compressed_parts.append(current)

    return "/".join(compressed_parts)

