def maxProfit(prices):
    """
    Finds the maximum profit that can be achieved by buying and selling one stock.

    :param prices: List of integers where each represents the stock price on a given day
    :return: Maximum profit that can be achieved. 0 if no profit can be made.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

