def min_jumps(arr):
    """
    Returns the minimum number of jumps required to reach the last index of the array,
    or -1 if it's not possible.
    """
    if len(arr) <= 1:
        return 0

    if arr[0] == 0:
        return -1

    max_reach = arr[0]
    step = arr[0]
    jump = 1

    for i in range(1, len(arr)):
        if i == len(arr) - 1:
            return jump

        max_reach = max(max_reach, i + arr[i])
        step -= 1

        if step == 0:
            jump += 1
            if i >= max_reach:
                return -1
            step = max_reach - i

    return -1

