def find_even_and_divisible_by_3(arr):
    """
    Returns the first element that is both even and divisible by 3, or -1 if no such element exists in the array.

    :param arr: List of integers.
    :return: The first integer that is even and divisible by 3, or -1 if no such element exists.
    """
    for num in arr:
        if num % 2 == 0 and num % 3 == 0:
            return num
    return -1
